-- All Agentic options and mappings are data generated by default.nix.
local settings = require("dotfiles.settings")
local agentic = require("agentic")

agentic.setup(settings.agentic)

for _, binding in ipairs(settings.agenticMappings) do
  vim.keymap.set(binding.modes, binding.lhs, assert(agentic[binding.action]), {
    desc = binding.desc,
    silent = true,
  })
end
